import {tracks} from './content.mjs';
const main=document.querySelector('main'),status=document.querySelector('#audio-status'),toggle=document.querySelector('#listen-toggle');
const KEY='english-quest-academy-v1';
const lessonTotal=tracks.reduce((n,t)=>n+t.lessons.length,0);
const wordTotal=tracks.reduce((n,t)=>n+t.lessons.reduce((m,l)=>m+l.words.length,0),0);
const questionTotal=tracks.reduce((n,t)=>n+t.lessons.reduce((m,l)=>m+l.questions.length,0),0);
let saved={completed:[],wrong:[],notes:{},position:{},known:[],rate:1};
try{const s=JSON.parse(localStorage.getItem(KEY));if(s&&Array.isArray(s.completed)&&Array.isArray(s.wrong))saved={...saved,...s};if(!saved.notes||typeof saved.notes!=='object'||Array.isArray(saved.notes))saved.notes={};if(!saved.position||typeof saved.position!=='object'||Array.isArray(saved.position))saved.position={};if(!Array.isArray(saved.known))saved.known=[];saved.completed=saved.completed.filter(x=>typeof x==='string');saved.wrong=saved.wrong.filter(x=>typeof x==='string');saved.known=saved.known.filter(x=>typeof x==='string');}catch{}
let current=null,mode='learn',index=0,revealed=false,answer=null,question=0,playing=false,token=0,timer=null;
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const id=(t,i)=>`${t.id}/${i}`;
const persist=()=>{try{localStorage.setItem(KEY,JSON.stringify(saved));}catch{status.textContent='Progress cannot be saved in this browser. You can keep learning.';}};
function stop(clear=true){token++;clearTimeout(timer);playing=false;window.speechSynthesis?.cancel();toggle.textContent='Listen';document.querySelectorAll('.word.active').forEach(el=>el.classList.remove('active'));if(clear)status.textContent='';}
function speak(text,done,version){const engine=window.speechSynthesis;if(!engine){stop(false);status.textContent='Speech is unavailable. Read the definition and example on each card.';return;}const u=new SpeechSynthesisUtterance(text);u.lang='en-US';u.rate=[.75,1,1.25].includes(Number(saved.rate))?Number(saved.rate):1;const voices=engine.getVoices();const voice=voices.find(v=>v.lang==='en-US')||voices.find(v=>v.lang.startsWith('en'));if(!voice){stop(false);status.textContent='No English voice is available. Enable an English voice on your device, then try again.';return;}u.voice=voice;u.onend=()=>{if(version===token)done();};u.onerror=()=>{if(version===token){stop(false);status.textContent='Speech stopped. Tap Listen to try again.';}};engine.speak(u);}
function listen(at=index,single=false){if(!current){status.textContent='Choose a lesson, then tap Listen.';return;}stop();index=at;playing=true;toggle.textContent='Stop audio';const version=token;function next(){if(version!==token)return;const w=current.lesson.words[index];if(!w){stop(false);status.textContent='Set complete. Try the flashcards or check your understanding.';return;}saved.position[current.key]=index;persist();status.textContent=`${index+1} / ${current.lesson.words.length} · ${w[0]}`;document.querySelectorAll('[data-word]').forEach(el=>el.classList.toggle('active',Number(el.dataset.word)===index));speak(`${w[0]}. ${w[1]}. ${w[2]}`,()=>{if(single){stop(false);status.textContent='Finished. Tap Listen to continue the set.';}else{index++;timer=setTimeout(next,900);}},version);}next();}
const links=(t,i)=>`<div class="steps" aria-label="Lesson modes">${['learn','words','cards','quiz'].map(m=>`<a href="#lesson/${id(t,i)}/${m}" ${m===mode?'aria-current="page"':''}>${{learn:'Learn',words:'Words & audio',cards:'Flashcards',quiz:'Practice'}[m]}</a>`).join('')}</div>`;
function render(){const parts=location.hash.slice(1).split('/');current=null;answer=null;question=0;revealed=false;mode=parts[3]||'learn';document.querySelectorAll('.dock a').forEach(a=>{if(a.hash==='#'+parts[0])a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});
 if(parts[0]==='lesson'){const t=tracks.find(t=>t.id===parts[1]),n=Number(parts[2]);if(t&&Number.isInteger(n)&&t.lessons[n]){current={track:t,n,lesson:t.lessons[n],key:id(t,n)};index=Math.min(Math.max(Number(saved.position[current.key])||0,0),current.lesson.words.length-1);const l=current.lesson;main.innerHTML=`<a href="#track/${t.id}">← ${t.name} lessons</a><p class="eyebrow">${t.name} · Lesson ${n+1}</p><h1>${esc(l.title)}</h1><p class="lead">${esc(l.goal)}</p>${links(t,n)}<div id="lesson-body"></div>`;renderMode();return;}}
 if(parts[0]==='track'){const t=tracks.find(t=>t.id===parts[1]);if(t){main.innerHTML=`<a href="#home">← All courses</a><p class="eyebrow">${t.tag}</p><h1>${t.name}</h1><p class="lead">${t.intro}</p><div class="grid">${t.lessons.map((l,i)=>`<article class="card"><p class="eyebrow">Lesson ${i+1}${saved.completed.includes(id(t,i))?' · Practiced':''}</p><h2>${l.title}</h2><p>${l.goal}</p><div class="actions"><a class="button primary" href="#lesson/${id(t,i)}/learn">Start lesson</a><a class="button" href="#lesson/${id(t,i)}/words">Listen to set</a></div></article>`).join('')}</div>`;return;}}
 if(parts[0]==='review'){main.innerHTML=`<p class="eyebrow">Retrieve · Explain · Retry</p><h1>Review your mistakes</h1><p>Read the explanation, then return to the lesson and try again.</p>${saved.wrong.length?saved.wrong.map(k=>{const [tid,n,q]=k.split('/');const t=tracks.find(t=>t.id===tid),l=t?.lessons[n],item=l?.questions[q];return item?`<article class="card"><h2>${esc(item[0])}</h2><p><strong>${esc(item[2])}</strong></p><p>${esc(item[3])}</p><a class="button" href="#lesson/${tid}/${n}/quiz">Retry ${t.name} practice</a></article>`:'';}).join(''):'<div class="card">No mistakes saved yet. Complete a practice check to build your review list.</div>'}`;return;}
 if(parts[0]==='progress'){const count=saved.completed.filter(k=>tracks.some(t=>t.lessons.some((_,i)=>id(t,i)===k))).length;main.innerHTML=`<p class="eyebrow">Your learning record</p><h1>${count} of ${lessonTotal} lessons practiced</h1><div class="meter" role="progressbar" aria-label="Lessons practiced" aria-valuemin="0" aria-valuemax="${lessonTotal}" aria-valuenow="${count}"><span style="width:${count/lessonTotal*100}%"></span></div><p>${saved.known.length} vocabulary entries marked as recalled.</p><p>This records completed practice checks. It is not an official score or a proficiency estimate.</p><a class="button primary" href="#review">Review mistakes (${saved.wrong.length})</a><div class="card"><p>Progress and notes are saved in this browser.</p><button data-action="reset">Reset my English academy progress</button><p id="reset-confirm"></p></div>`;return;}
 main.innerHTML=`<p class="eyebrow">English-only academy</p><h1>Understand it.<br>Say it. Use it.</h1><p class="lead">Build English for TOEFL, TOEIC, SAT, GMAT and GRE. Choose a course, study a short lesson, then listen to words and their English definitions.</p><div class="actions"><a class="button primary" href="#track/toefl">Explore TOEFL</a><a class="button" href="#review">Review mistakes</a></div><h2>Choose your course</h2><div class="grid">${tracks.map(t=>`<article class="card"><p class="eyebrow">${t.tag}</p><h2>${t.name}</h2><p>${t.intro}</p><div class="actions"><a class="button primary" href="#track/${t.id}">View lessons</a><a class="button" href="#lesson/${t.id}/0/words">Listen to a set</a></div></article>`).join('')}</div><div class="card"><h2>A complete learning cycle</h2><p>Learn the idea → explain it yourself → listen and repeat → recall with flashcards → practice → review mistakes.</p><p class="muted">Collection: ${lessonTotal} lessons, ${wordTotal} word and phrase entries, and ${questionTotal} original practice questions. Listening uses your device’s English speech voice and requires an available English voice. These lessons are independent learning materials, not official exam questions or a complete exam syllabus.</p><a href="../index.html">Open the full bilingual learning library ↗</a></div>`;
}
function renderMode(){const l=current.lesson,body=document.querySelector('#lesson-body');
 if(mode==='words'){body.innerHTML=`<section class="card"><h2>Listen and repeat</h2><p>Hear each word or phrase, its English definition, and an example. Pause after each example and explain the meaning in your own words.</p><div class="settings"><button class="primary" data-action="play">Play this set</button><label>Speed <select id="speed">${[.75,1,1.25].map(r=>`<option value="${r}" ${Number(saved.rate)===r?'selected':''}>${r}×</option>`).join('')}</select></label></div><p class="muted">The Listen button resumes from the most recent word. Changing lessons stops speech.</p></section><div class="word-list">${l.words.map((w,i)=>`<article class="word" data-word="${i}"><div><strong>${esc(w[0])}</strong><p>${esc(w[1])}</p><p class="muted">${esc(w[2])}</p></div><button data-say="${i}" aria-label="Listen to ${esc(w[0])}">▶</button></article>`).join('')}</div>`;return;}
 if(mode==='cards'){const w=l.words[index];body.innerHTML=`<section class="card flash"><p class="eyebrow">Card ${index+1} of ${l.words.length}</p><h2>${esc(w[0])}</h2>${revealed?`<p>${esc(w[1])}</p><p class="muted">${esc(w[2])}</p>`:'<p>Recall the meaning and say an example before revealing.</p>'}<div class="actions"><button data-action="reveal">${revealed?'Hide meaning':'Reveal meaning'}</button><button data-say="${index}">Hear word & definition</button>${revealed?`<button data-action="known">${saved.known.includes(current.key+'/'+index)?'Marked as recalled ✓':'I recalled this'}</button><button data-action="again">Practice again</button>`:''}</div></section><div class="actions"><button data-action="previous" ${index===0?'disabled':''}>← Previous</button><button class="primary" data-action="next" ${index===l.words.length-1?'disabled':''}>Next →</button></div>`;return;}
 if(mode==='quiz'){renderQuestion();return;}
 body.innerHTML=`<section class="card"><h2>The idea</h2><p>${esc(l.rule)}</p></section><section class="card"><h2>Worked example</h2><p>${esc(l.example)}</p><button data-action="example">Listen to the example</button></section><section class="card"><h2>Your turn</h2><p>${esc(l.task)}</p><label for="reflection">Your explanation</label><textarea id="reflection" placeholder="Explain the idea in your own words.">${esc(saved.notes[current.key]||'')}</textarea><p class="muted">Saved on this device. Compare your reasoning with the worked example.</p></section><div class="actions"><a class="button primary" href="#lesson/${current.key}/words">Learn the word set</a><a class="button" href="#lesson/${current.key}/quiz">Check understanding</a></div>`;
}
function renderQuestion(){const body=document.querySelector('#lesson-body'),l=current.lesson;if(question>=l.questions.length){saved.completed=[...new Set([...saved.completed,current.key])];persist();body.innerHTML=`<section class="card"><h2>Practice complete</h2><p>Explain one idea from this lesson without looking. Revisit any mistakes to strengthen your reasoning.</p><div class="actions"><a class="button primary" href="#review">Review mistakes</a><a class="button" href="#track/${current.track.id}">Choose another lesson</a></div></section>`;return;}const q=l.questions[question];const order=q[1].map((a,i)=>({a,i}));const offset=(current.n+question+current.track.id.length)%order.length;order.push(...order.splice(0,offset));body.innerHTML=`<section class="card"><p class="eyebrow">Question ${question+1} of ${l.questions.length}</p><h2>${esc(q[0])}</h2><div class="answers">${order.map(({a,i})=>`<button data-answer="${i}" ${answer!==null?'disabled':''}>${esc(a)}</button>`).join('')}</div>${answer!==null?`<div class="feedback ${q[1][answer]===q[2]?'':'incorrect'}" role="status"><strong>${q[1][answer]===q[2]?'Correct.':'Review the reasoning.'}</strong><p>Answer: ${esc(q[2])}</p><p>${esc(q[3])}</p><button class="primary" data-action="question-next">${question+1===l.questions.length?'Finish practice':'Next question'}</button></div>`:''}</section>`;}
main.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.say!==undefined){listen(Number(b.dataset.say),true);return;}if(b.dataset.answer!==undefined&&current&&answer===null){answer=Number(b.dataset.answer);const q=current.lesson.questions[question],k=`${current.key}/${question}`;saved.wrong=saved.wrong.filter(x=>x!==k);if(q[1][answer]!==q[2])saved.wrong.push(k);persist();renderQuestion();return;}const a=b.dataset.action;if(a==='reset'){document.querySelector('#reset-confirm').innerHTML='Clear all saved progress and notes? <button data-action="confirm-reset">Yes, clear progress</button>';return;}if(a==='confirm-reset'){saved={completed:[],wrong:[],notes:{},position:{},known:[],rate:1};persist();render();return;}if(!current)return;if(a==='play')listen(0);if(a==='example'){stop();playing=true;toggle.textContent='Stop audio';speak(current.lesson.example,()=>stop(),token);}if(a==='known'||a==='again'){const k=current.key+'/'+index;saved.known=saved.known.filter(x=>x!==k);if(a==='known')saved.known.push(k);persist();renderMode();}if(a==='reveal'){revealed=!revealed;renderMode();}if(a==='previous'||a==='next'){stop();index=Math.max(0,Math.min(current.lesson.words.length-1,index+(a==='next'?1:-1)));revealed=false;saved.position[current.key]=index;persist();renderMode();}if(a==='question-next'){question++;answer=null;renderQuestion();}});
main.addEventListener('input',e=>{if(e.target.id==='reflection'&&current){saved.notes[current.key]=e.target.value;persist();}});
main.addEventListener('change',e=>{if(e.target.id==='speed'){saved.rate=Number(e.target.value);persist();if(playing)listen(index);}});
toggle.addEventListener('click',()=>playing?stop():listen(index));
window.addEventListener('hashchange',()=>{stop();render();main.focus();window.scrollTo(0,0);});window.addEventListener('pagehide',()=>stop());render();
